import {World} from './world.js';
import {FallbackWorld} from './fallback.js';
import {fresh,restore,Economy,FishingSystem,SharkAI,clamp,castProfile,pingPong,bobberPos,rarityInfo} from './systems.js';
import {MinigameView,CatchReveal,drawSpeciesFish} from './minigame.js';
import {FISH,UPGRADES,SHOALS,BALANCE} from './config.js';
const $=id=>document.getElementById(id);let state;try{state=restore(localStorage.getItem('o-pescador-v1'));}catch{state=fresh();}
const economy=new Economy(state),fishing=new FishingSystem(state),shark=new SharkAI();const boat={x:0,z:0,angle:0,speed:0};let world;try{world=new World($('world'));}catch(e){world=new FallbackWorld($('world'));console.warn('WebGL indisponível: modo 2D simplificado ativado.');}
world.quality(state.settings.quality);let playing=state.intro,paused=false,orbit=.25,reel=false,spear=false,clock=0,storm=0,stormTarget=0,weatherTimer=170,saveTimer=0,toastTimer=0,uiTimer=0,prev=performance.now(),tab='buyer',lastFishState='idle',ac,audioGain,motorOsc;const keys=new Set();
let charging=false,chargeT=0,power=0,invTab='hold';const minigame=new MinigameView($('mgCanvas')),reveal=new CatchReveal($('revealCanvas'),$('catchReveal'),{weight:$('revealWeight'),price:$('revealPrice')});
$('revealClose').onclick=$('catchReveal').onclick=()=>reveal.hide();
$('intro').hidden=playing;
function audio(){if(ac)return;try{ac=new (window.AudioContext||window.webkitAudioContext)();audioGain=ac.createGain();audioGain.gain.value=state.settings.volume*.13;audioGain.connect(ac.destination);motorOsc=ac.createOscillator();motorOsc.type='sine';motorOsc.frequency.value=45;const gain=ac.createGain();gain.gain.value=.07;motorOsc.connect(gain);gain.connect(audioGain);motorOsc.start();const buffer=ac.createBuffer(1,ac.sampleRate*3,ac.sampleRate);const data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.22;const source=ac.createBufferSource();source.buffer=buffer;source.loop=true;const filter=ac.createBiquadFilter();filter.type='lowpass';filter.frequency.value=450;source.connect(filter);filter.connect(audioGain);source.start();}catch{}}
function beep(freq=500){if(!ac)return;const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=freq;o.connect(g);g.connect(audioGain);g.gain.setValueAtTime(.4,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.25);o.start();o.stop(ac.currentTime+.25);}
function fanfare(tier=1){if(!ac)return;const notes=[523,659,784,987,1175,1568].slice(0,1+tier);notes.forEach((f,i)=>{const t0=ac.currentTime+i*.085,o=ac.createOscillator(),g=ac.createGain();o.type=tier>=4?'triangle':'sine';o.frequency.value=f;o.connect(g);g.connect(audioGain);g.gain.setValueAtTime(.36,t0);g.gain.exponentialRampToValueAtTime(.001,t0+.32);o.start(t0);o.stop(t0+.32);});}
function showCatchReveal(def,weight,price,stored=true){const r=rarityInfo(def),ratio=(weight-def.min)/Math.max(.1,def.max-def.min),sizeTag=ratio>.85?'Troféu colossal!':ratio>.55?'Acima da média':ratio>.25?'Bom exemplar':'Exemplar jovem';$('revealEyebrow').textContent=stored?'PEIXE CAPTURADO!':'CAPTURADO (PORÃO CHEIO)';$('revealRarity').textContent=`${def.rarity.toUpperCase()} ${r.stars}`;$('revealTitle').textContent=def.name;$('revealDesc').textContent=def.desc||'';$('revealSizeTag').textContent=sizeTag;$('revealRateTag').textContent=`◈ ${def.price} / kg`;$('revealClose').innerHTML=stored?'Guardar no porão <span>✓</span>':'Continuar <span>→</span>';reveal.show({species:def.id,weight},def,price);fanfare(r.tier);}
function toast(msg){$('toast').textContent=msg;$('toast').style.opacity=1;toastTimer=4;}
function save(){try{localStorage.setItem('o-pescador-v1',JSON.stringify(state));$('saveStatus').textContent='● Progresso salvo';}catch{$('saveStatus').textContent='! Salvamento indisponível';}}
function start(){playing=true;state.intro=true;$('intro').hidden=true;audio();save();toast('Bem-vindo à costa. Use W A S D para navegar e F para pescar.');}
$('start').onclick=$('skip').onclick=start;
const distance=()=>Math.hypot(boat.x,boat.z);const zone=()=>distance()>330?2:distance()>130?1:0;const docked=()=>distance()<24;const shoalDistance=()=>Math.min(...SHOALS.map(p=>Math.hypot(p.x-boat.x,p.z-boat.z)));
// Lançamento com força: segure para carregar (a barra vai e volta), solte para lançar.
function startCharge(){if(!playing||paused||charging||fishing.state!=='idle')return;if(economy.weight>=economy.capacity-.3){toast('Porão cheio. Volte ao porto para vender a carga.');return;}if(Math.abs(boat.speed)>2){toast('Reduza a velocidade antes de lançar a linha.');return;}spear=false;boat.speed=0;charging=true;chargeT=0;power=0;audio();beep(260);}
function releaseCharge(){if(!charging)return;charging=false;if(paused||!playing)return;const profile=castProfile(power);fishing.cast(zone(),shoalDistance()<18,storm>.4?'rain':'calm',power);beep(profile.perfect?900:350);toast(`${profile.label} · ${Math.round(profile.distance)} m`);}
function cancelCharge(){charging=false;}
function tryHook(){if(fishing.state!=='bite')return;if(fishing.hook()){beep(800);minigame.flash('#9ff0b0');toast('Fisgado! Mantenha o peixe dentro da zona.');}else{beep(170);minigame.flash('#e8806b');$('minigame').classList.remove('shake');void $('minigame').offsetWidth;$('minigame').classList.add('shake');if(fishing.state==='idle')toast('Você puxou na hora errada e o peixe fugiu.');else toast('Errou o tempo! Última tentativa.');}}
// Ação principal (F / Espaço / botão / toque no minigame): pressionar e soltar.
function actionDown(){if(!playing||paused)return;if(reveal.active){if(reveal.t>.35)reveal.hide();return;}if(fishing.state==='idle')startCharge();else if(fishing.state==='bite')tryHook();else if(fishing.state==='reeling')reel=true;}
function actionUp(){if(charging)releaseCharge();reel=false;}
function cast(){actionDown();actionUp();}
function attack(){if(!playing||paused)return;if(!spear){spear=true;fishing.cancel();toast('Lança equipada. Pressione Q novamente quando o tubarão se aproximar.');return;}if(shark.hit(8+state.upgrades.spear*1.5)){if(state.upgrades.spear>0)shark.hp-=state.upgrades.spear*.5;beep(180);toast(shark.hp<=0?'O tubarão está se afastando.':'Acertou! Mantenha a atenção.');}else toast('Fora de alcance. Espere a aproximação e pressione Q.');}
function open(html){paused=true;keys.clear();reel=false;charging=false;$('modalContent').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function close(){$('modal').close();paused=false;keys.clear();reel=false;save();}
$('closeModal').onclick=close;$('modal').addEventListener('cancel',e=>{e.preventDefault();close();});
const BOAT_STAGES=[
  ['Velho Companheiro','Casco tradicional de madeira costeira, bancos rústicos e motor compacto.'],
  ['Brisa Forte','Casco azul-oceano, console com timão, para-brisa frontal, farol de proa e caixa térmica.'],
  ['Estrela do Norte','Casco branco naval, cabine aberta (T-Top), guarda-corpo metálico, luzes de navegação e motor duplo.'],
  ['Soberano dos Mares','O ápice naval: casco Azul-Imperial & Ouro, radar giratório no teto, 4 porta-varas dourados, holofotes e proa astral.']
];
const ROD_STAGES=[
  ['Bambu Artesanal','Vara simples de bambu com nós amarrados em corda.'],
  ['Fibra Costeira','Vara azul-marinho com molinete lateral metálico e passadores cromados.'],
  ['Carbono & Ouro','Vara oceânica em fibra de carbono grafite, anéis dourados e carretilha dupla.'],
  ['Soberana do Abismo','A melhor vara: ouro polido, espiral bioluminescente ciano, guarda real e rotor luminoso giratório.']
];
function paintFishIcons(){for(const cv of document.querySelectorAll('canvas[data-fishicon]')){const def=FISH.find(x=>x.id===cv.dataset.fishicon);if(!def)continue;const c=cv.getContext('2d');c.clearRect(0,0,cv.width,cv.height);drawSpeciesFish(c,def,cv.width*.52,cv.height*.54,15,1,.4,1.2,1);}}
function inventory(next=invTab){invTab=next;const zones=['Costa da Esperança','Mar aberto','Águas profundas'],bt=Math.max(state.upgrades.hull||0,state.upgrades.motor||0,state.upgrades.hold||0);let body='';if(invTab==='catalog')body=`<p>Conheça os ${FISH.length} estilos de peixes das 5 raridades e veja a animação de cada um.</p>`+FISH.map(def=>{const r=rarityInfo(def);return `<div class="row"><div class="fishcell"><canvas class="fishicon" data-fishicon="${def.id}" width="78" height="46"></canvas><div><strong style="color:${r.color}">${def.name} <span class="pill" style="color:${r.color}">${def.rarity} ${r.stars}</span></strong><small>${def.desc}</small><small>${zones[def.zone]} · Vara nv. ${def.rod+1} · ${def.min}–${def.max} kg · ◈ ${def.price}/kg</small></div></div><button data-preview="${def.id}">Ver animação</button></div>`;}).join('');else if(invTab==='evo')body=`<p>O barco e a vara evoluem visualmente a cada nível (compre melhorias no Porto ou clique abaixo para testar o visual no mar).</p><div class="eyebrow" style="margin-top:14px">EVOLUÇÕES DO BARCO (ATUAL: NÍVEL ${bt+1})</div>`+BOAT_STAGES.map(([n,d],i)=>`<div class="row"><div><strong style="color:${i===3?'#ffd86b':i===bt?'#9fd8c9':'inherit'}">Nível ${i+1} · ${n} ${i===3?'★ MÁXIMO':''}</strong><small>${d}</small></div><button data-test-boat="${i}">${bt===i?'Em uso':'Ver Nv. '+(i+1)}</button></div>`).join('')+`<div class="eyebrow" style="margin-top:18px">EVOLUÇÕES DA VARA (ATUAL: NÍVEL ${state.upgrades.rod+1})</div>`+ROD_STAGES.map(([n,d],i)=>`<div class="row"><div><strong style="color:${i===3?'#6cf5ff':i===state.upgrades.rod?'#9fd8c9':'inherit'}">Nível ${i+1} · ${n} ${i===3?'★ MÁXIMO':''}</strong><small>${d}</small></div><button data-test-rod="${i}">${state.upgrades.rod===i?'Em uso':'Ver Nv. '+(i+1)}</button></div>`).join('');else body=`<p>Cada captura tem uma história. Leve-as ao comprador no porto.</p><div class="summary"><span>${economy.weight.toFixed(1)} / ${economy.capacity} kg</span><span>Valor estimado: ◈ ${state.inventory.reduce((a,f)=>a+economy.price(f),0)}</span></div>${fishRows(false)}`;open(`<div class="eyebrow">${BOAT_STAGES[bt][0].toUpperCase()}</div><h2>Seu porão</h2><div class="tabs"><button data-invtab="hold" class="${invTab==='hold'?'active':''}">Carga atual</button><button data-invtab="catalog" class="${invTab==='catalog'?'active':''}">Catálogo (${FISH.length} peixes)</button><button data-invtab="evo" class="${invTab==='evo'?'active':''}">Evoluções (Barco e Vara)</button></div>${body}`);paintFishIcons();}
function fishRows(sell){return state.inventory.length?state.inventory.map(f=>{const def=FISH.find(x=>x.id===f.species),r=rarityInfo(def);return `<div class="row"><div class="fishcell"><canvas class="fishicon" data-fishicon="${def.id}" width="78" height="46"></canvas><div><strong style="color:${r.color}">${def.name}</strong><small>${def.rarity} ${r.stars} · ${f.weight.toFixed(2)} kg · ◈ ${economy.price(f)}</small></div></div>${sell?`<button data-sell="${f.id}">Vender · ◈ ${economy.price(f)}</button>`:`<button data-preview-item="${f.id}">Ver peixe · ◈ ${economy.price(f)}</button>`}</div>`;}).join(''):'<p class="muted">Ainda não há peixes no porão. As águas costeiras são um bom começo.</p>';}
function port(next=tab){if(!docked()){toast('O porto está a '+Math.round(distance())+' m. Volte ao marcador de âncora no mapa.');return;}tab=next;boat.speed=0;fishing.cancel();let content='';if(tab==='buyer')content=`<p>Bom te ver de volta. Vamos pesar sua pescaria?</p>${fishRows(true)}<div class="summary"><span>${economy.weight.toFixed(1)} kg a bordo</span><span>◈ ${state.inventory.reduce((a,f)=>a+economy.price(f),0)}</span></div><button class="primary" data-sell="all" ${state.inventory.length?'':'disabled'}>Vender toda a carga</button>`;if(tab==='gear')content=Object.entries(UPGRADES).map(([k,u])=>{const lv=state.upgrades[k],max=lv===u.max;return `<div class="row"><div><strong>${u.name} <span class="pill">${lv} / ${u.max}</span></strong><small>${u.desc}</small></div><button data-buy="${k}" ${max||state.money<u.prices[lv]?'disabled':''}>${max?'Completo':'◈ '+u.prices[lv]}</button></div>`;}).join('');if(tab==='service')content=`<p>Cuide do barco e de quem espera por você.</p>${[['fuel','Tanque cheio','Combustível para a próxima viagem',18],['hull','Reparar casco','Restaura a integridade do barco',25],['food','Alimentos para casa','Avança a missão da família',30]].map(([k,n,d,p])=>`<div class="row"><div><strong>${n}</strong><small>${d}</small></div><button data-service="${k}" ${state.money<p||(k!=='food'&&state[k]>=100)?'disabled':''}>◈ ${p}</button></div>`).join('')}<p class="muted">Sem combustível? Ainda é possível remar devagar. Um resgate também está disponível no menu de pausa.</p>`;
open(`<div class="eyebrow">COSTA DA ESPERANÇA · PORTO SEGURO</div><h2>De volta a casa <span class="pill">◈ ${state.money}</span></h2><div class="tabs"><button data-tab="buyer" class="${tab==='buyer'?'active':''}">Comprador</button><button data-tab="gear" class="${tab==='gear'?'active':''}">Melhorias</button><button data-tab="service" class="${tab==='service'?'active':''}">Suprimentos</button></div>${content}`);paintFishIcons();}
function missions(){open(`<div class="eyebrow">SUA JORNADA</div><h2>Uma vida junto ao mar</h2><p>Melhore suas condições de vida no seu ritmo. Sua família não perde progresso enquanto você explora.</p>${[[state.sold>0,'A primeira venda','Capture e venda pelo menos um peixe.'],[state.fed>0,'À mesa, juntos','Compre alimentos no porto.'],[state.upgrades.home>0,'Um teto melhor','Compre a primeira melhoria da casa.'],[state.upgrades.motor>=1&&state.upgrades.rod>=2,'Além do horizonte','Motor nível 1 e vara nível 2 liberam águas profundas.'],[state.upgrades.home===3,'Um lugar para recomeçar','Complete as três melhorias da casa.']].map(([done,n,d])=>`<div class="row"><div><strong>${done?'✓':'◇'} ${n}</strong><small>${d}</small></div><span class="pill">${done?'Concluído':'Em andamento'}</span></div>`).join('')}`);}
function settings(){open(`<div class="eyebrow">DO SEU JEITO</div><h2>Configurações</h2><div class="row"><div>Qualidade gráfica<small>Resolução e sombras. Alta exige mais da GPU.</small></div><select id="quality">${['Baixa','Média','Alta'].map(v=>`<option ${state.settings.quality===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="row"><label for="volume">Volume dos sons</label><input id="volume" type="range" min="0" max="1" step=".05" value="${state.settings.volume}"></div><p>W/S: acelerar e dar ré · A/D: virar · F ou Espaço: segure e solte para lançar com força, aperte para fisgar, segure para recolher · E: porto · Q: equipar/atacar com lança · I: porão · Esc: pausa.</p><p>Solte o lançamento na faixa dourada para um lançamento perfeito (espera menor e mais chance de peixes raros). Na fisgada, aperte quando a agulha passar pelo dourado. Na captura, mantenha o peixe dentro da zona verde até encher a barra. No celular, use as setas e o botão de recolhimento.</p><p class="muted">Salvamento local neste navegador. Não sincroniza entre dispositivos.</p>`);$('quality').onchange=e=>{state.settings.quality=e.target.value;world.quality(e.target.value);save();};$('volume').oninput=e=>{state.settings.volume=Number(e.target.value);if(audioGain)audioGain.gain.value=state.settings.volume*.13;save();};}
function pause(){if($('modal').open){close();return;}open('<div class="eyebrow">UM MOMENTO DE CALMA</div><h2>O mar pode esperar.</h2><p>Seu progresso está salvo. A simulação fica pausada enquanto este menu está aberto.</p><div class="row"><button id="resume" class="primary">Continuar viagem</button><button id="rescue">Pedir resgate ao porto</button></div><p class="muted">O resgate preserva suas melhorias e seu dinheiro, mas a carga é perdida. O casco e o combustível são parcialmente restaurados.</p>');$('resume').onclick=close;$('rescue').onclick=()=>{rescue();close();};save();}
function rescue(){boat.x=boat.z=boat.speed=boat.angle=0;state.hull=Math.max(45,state.hull);state.fuel=Math.max(25,state.fuel);state.inventory=[];shark.reset();fishing.cancel();save();toast('Você chegou em segurança. A carga foi perdida durante o resgate.');}
function map(){open('<div class="eyebrow">CARTA NÁUTICA</div><h2>Um oceano de possibilidades</h2><canvas id="mapLarge" width="600" height="400"></canvas><p>⚓ Porto · ▲ Seu barco · círculos: zonas costeira, aberta e profunda.</p><p>'+ (state.upgrades.sonar?'Pontos dourados: cardumes detectados pelo sonar.':'Instale o sonar para revelar a posição dos cardumes.')+'</p><p class="muted">Águas profundas: motor nível 1 e vara nível 2. Limite de exploração: 650 m do porto.</p>');drawMap($('mapLarge'),true);}
$('modalContent').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.invtab)inventory(b.dataset.invtab);if(b.dataset.testBoat!=null){const lv=Number(b.dataset.testBoat);state.upgrades.hull=state.upgrades.motor=state.upgrades.hold=lv;close();beep(750);toast(`Visual do barco: Nível ${lv+1} (${BOAT_STAGES[lv][0]}) ativado!`);}if(b.dataset.testRod!=null){const lv=Number(b.dataset.testRod);state.upgrades.rod=lv;close();beep(820);toast(`Visual da vara: Nível ${lv+1} (${ROD_STAGES[lv][0]}) ativado!`);}if(b.dataset.preview){const def=FISH.find(x=>x.id===b.dataset.preview);if(def){close();audio();const w=Math.round((def.min+def.max)*50)/100;showCatchReveal(def,w,Math.round(def.price*w));}}if(b.dataset.previewItem){const item=state.inventory.find(x=>x.id===b.dataset.previewItem),def=item&&FISH.find(x=>x.id===item.species);if(def){close();audio();showCatchReveal(def,item.weight,economy.price(item));}}if(b.dataset.tab)port(b.dataset.tab);if(b.dataset.sell){if(!docked())return;const amount=economy.sell(b.dataset.sell);save();port();if(amount){beep(950);toast('Venda concluída: +'+amount+' moedas.');}}if(b.dataset.buy){if(!docked())return;if(economy.buy(b.dataset.buy)){beep(700);save();port();toast('Melhoria instalada. Seu barco está pronto para mais.');}}if(b.dataset.service){if(!docked())return;if(economy.service(b.dataset.service)){beep(600);save();port();toast('Tudo pronto. Boa viagem!');}}};
function holdButton(el){el.onpointerdown=e=>{e.preventDefault();el.setPointerCapture?.(e.pointerId);actionDown();};el.onpointerup=el.onpointercancel=()=>actionUp();el.onkeydown=e=>{if(e.key==='Enter'&&!e.repeat){e.preventDefault();e.stopPropagation();actionDown();}};el.onkeyup=e=>{if(e.key==='Enter'){e.stopPropagation();actionUp();}};}
holdButton($('fishBtn'));holdButton($('mgAction'));holdButton($('mgCanvas'));$('mgCancel').onclick=()=>{fishing.cancel();reel=false;toast('Você soltou a linha.');};
$('inventory').onclick=inventory;$('shop').onclick=()=>port();$('spear').onclick=attack;$('missions').onclick=missions;$('mapOpen').onclick=map;$('settings').onclick=settings;$('pause').onclick=pause;$('cancelFish').onclick=()=>{fishing.cancel();reel=false;};$('fishAction').onpointerdown=e=>{e.preventDefault();actionDown();};$('fishAction').onpointerup=$('fishAction').onpointercancel=()=>actionUp();
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.key==='Escape'){if(charging){cancelCharge();return;}if(playing)pause();return;}if(!playing||paused)return;audio();keys.add(e.key.toLowerCase());if(e.key.toLowerCase()==='f'||e.code==='Space')actionDown();if(e.key.toLowerCase()==='q')attack();if(e.key.toLowerCase()==='e')port();if(e.key.toLowerCase()==='i')inventory();});addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());if(e.key.toLowerCase()==='f'||e.code==='Space')actionUp();});addEventListener('blur',()=>{keys.clear();reel=false;charging=false;if(playing&&!paused)pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});addEventListener('pagehide',e=>{save();if(!e.persisted)world.dispose?.();});
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key);}
let drag=false,lastX=0;world.renderer.domElement.onpointerdown=e=>{drag=true;lastX=e.clientX;world.renderer.domElement.setPointerCapture(e.pointerId);};world.renderer.domElement.onpointermove=e=>{if(drag){orbit-=(e.clientX-lastX)*.006;lastX=e.clientX;}};world.renderer.domElement.onpointerup=world.renderer.domElement.onpointercancel=()=>drag=false;
function drawMap(canvas,large=false){const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height,scale=large?.48:.23,cx=w*.5,cy=large?h*.83:h*.7;c.fillStyle='#14353e';c.fillRect(0,0,w,h);c.strokeStyle='#7299991c';c.lineWidth=1;for(let x=0;x<w;x+=30){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}for(let y=0;y<h;y+=30){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}c.fillStyle='#486055';c.beginPath();c.moveTo(0,cy+20);c.bezierCurveTo(w*.3,cy-10,w*.45,cy+45,w,cy+8);c.lineTo(w,h);c.lineTo(0,h);c.fill();for(const r of [130,330,650]){c.strokeStyle='#9ab4ab25';c.beginPath();c.arc(cx,cy,r*scale,0,Math.PI*2);c.stroke();}c.fillStyle='#d8c498';c.font='15px sans-serif';c.fillText('⚓',cx-7,cy+9);if(state.upgrades.sonar)for(const p of SHOALS){c.beginPath();c.arc(cx+p.x*scale,cy+p.z*scale,3,0,7);c.fill();}const px=clamp(cx+boat.x*scale,8,w-8),py=clamp(cy+boat.z*scale,8,h-8);c.save();c.translate(px,py);c.rotate(-boat.angle);c.fillStyle='#ecede1';c.beginPath();c.moveTo(0,-7);c.lineTo(-4,5);c.lineTo(0,3);c.lineTo(4,5);c.closePath();c.fill();c.restore();}
function ui(){const z=zone();$('region').textContent=['Costa da Esperança','Mar aberto','Águas profundas'][z];const hr=Math.floor(state.time)%24,min=Math.floor(state.time%1*60);$('weather').textContent=`${String(hr).padStart(2,'0')}:${String(min).padStart(2,'0')} · ${storm>.5?'Chuva no mar':storm>.15?'Céu encoberto':'Brisa suave'}`;$('coins').textContent='◈ '+state.money;$('hold').textContent=economy.weight.toFixed(1)+' / '+economy.capacity+' kg';$('speed').textContent=(Math.abs(boat.speed)*1.94).toFixed(1);$('bearing').textContent='RUMO '+String((Math.round(-boat.angle*180/Math.PI)%360+360)%360).padStart(3,'0')+'°';$('depth').textContent=Math.round(12+distance()*.36)+' m de profundidade';for(const k of ['hull','fuel']){$(k+'Num').textContent=Math.round(state[k])+'%';$(k+'Bar').style.width=state[k]+'%';}const bt=Math.max(state.upgrades.hull||0,state.upgrades.motor||0,state.upgrades.hold||0);if($('boatTitle'))$('boatTitle').textContent=BOAT_STAGES[bt][0].toUpperCase();$('boatLevel').textContent=`Barco Nv.${bt+1} · Vara ${ROD_STAGES[state.upgrades.rod][0]} (Nv.${state.upgrades.rod+1})`;$('fishing').hidden=fishing.state!=='waiting';$('reelBars').hidden=true;const mg=fishing.state==='bite'||fishing.state==='reeling';$('minigame').classList.toggle('show',mg);if(mg){const fd=fishing.fish,r=rarityInfo(fd);$('minigame').dataset.rarity=fd.rarity;$('mgEyebrow').textContent=fishing.state==='bite'?'É AGORA! ALGO MORDEU':'VOCÊ E O MAR';$('mgTitle').textContent=fishing.state==='bite'?'Fisgue no tempo certo':fd.name;$('mgRarity').textContent=`${fd.rarity} ${r.stars}`;$('mgRarity').style.color=r.color;$('mgHelp').textContent=fishing.state==='bite'?'Aperte F, Espaço ou toque quando a agulha branca passar pela faixa dourada.':'Segure F, Espaço ou toque para subir a zona verde. Solte para descer. Mantenha o peixe dentro dela!';$('mgAction').textContent=fishing.state==='bite'?'Fisgar · F':'Segure para recolher · F';}$('fishState').textContent={waiting:'LINHA NA ÁGUA',bite:'É AGORA!',reeling:'VOCÊ E O MAR'}[fishing.state]||'';$('fishTitle').textContent={waiting:'À espera de uma mordida…',bite:'Um peixe mordeu!',reeling:fishing.fish?.name||'Recolhendo'}[fishing.state]||'';$('fishHelp').textContent={waiting:`Linha a ${Math.round(fishing.castDistance)} m. Observe a boia, o minigame vai subir do fundo quando algo morder.`,bite:'Pressione F ou toque em Fisgar antes que ele escape.',reeling:'Segure para recolher. Solte para aliviar a tensão.'}[fishing.state]||'';$('fishAction').textContent=fishing.state==='reeling'?'Segure para recolher · Espaço':'Fisgar · F';$('fishAction').disabled=fishing.state==='waiting';$('progress').style.width=fishing.progress*100+'%';$('tension').style.width=fishing.tension*100+'%';$('tension').style.background=fishing.tension>.8?'#df806b':'#e0b574';$('capturePercent').textContent=Math.round(fishing.progress*100)+'%';$('spear').style.borderColor=spear?'#e2bd79':'';const danger=shark.state!=='away';$('danger').style.display=danger?'block':'none';$('danger').textContent=shark.state==='retreat'?'O tubarão recuou. Fique atento.':`Barbatana à vista · ${Math.round(shark.distance)} m · Q para defender`;
const mission=state.sold===0?['O mar também é um lar.','Capture seu primeiro peixe e leve um pouco de esperança para casa.','Venda sua primeira captura',0]:state.fed===0?['Algo bom sobre a mesa.','Volte ao porto e compre alimentos para sua família.','Compre alimentos',0]:state.upgrades.home<3?['Uma casa, um recomeço.','Invista na casa da família e explore novos horizontes.','Melhore a casa',state.upgrades.home]:['É bom voltar para casa.','Sua família está bem. O oceano ainda guarda histórias.','Casa renovada',3];$('missionTitle').textContent=mission[0];$('missionText').textContent=mission[1];$('task').textContent=mission[2];$('taskProgress').textContent=mission[3]+' / '+(state.sold>0&&state.fed>0?3:1);drawMap($('minimap'));}
function powerUI(){const m=$('powerMeter');m.hidden=!charging;if(!charging)return;const p=castProfile(power);$('powerValue').textContent=Math.round(power*100)+'%';$('powerNeedle').style.left=power*100+'%';$('powerFill').style.width=power*100+'%';$('powerLabel').textContent=p.perfect?'Perfeito! Solte agora':`Solte para lançar · ${Math.round(p.distance)} m`;m.classList.toggle('perfect',p.perfect);}
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-prev)/1000,.05);prev=now;if(!paused){clock+=dt;if(playing){state.time=(state.time+dt/100)%24;weatherTimer-=dt;if(weatherTimer<=0){stormTarget=stormTarget?0:1;weatherTimer=150+Math.random()*100;toast(stormTarget?'Nuvens se aproximam. O vento vai aumentar.':'O céu está abrindo novamente.');}storm+=(stormTarget-storm)*dt*.025;boat.enginePower=0;if(fishing.state==='idle'&&!charging){const throttle=(keys.has('w')?1:0)-(keys.has('s')?1:0),maxSpeed=state.fuel>0?(7+state.upgrades.motor*2.5)*(1-storm*.15):1.4;boat.enginePower=state.fuel>0?Math.abs(throttle):0;boat.speed+=throttle*dt*3;boat.speed*=Math.exp(-dt*(throttle?.12:.8));boat.speed=clamp(boat.speed,-maxSpeed*.35,maxSpeed);const steer=(keys.has('a')?1:0)-(keys.has('d')?1:0);boat.angle+=steer*dt*.85*(.25+Math.min(Math.abs(boat.speed)/4,1));const nx=boat.x-Math.sin(boat.angle)*boat.speed*dt,nz=boat.z-Math.cos(boat.angle)*boat.speed*dt,nd=Math.hypot(nx,nz);if(nz>7&&Math.abs(nx)<180){boat.speed*=-.2;}else if(nd>330&&(state.upgrades.motor<1||state.upgrades.rod<2)||nd>650){boat.speed*=-.2;if(toastTimer<=0)toast(nd>650?'Fim da área de navegação.':'Águas profundas exigem motor nível 1 e vara nível 2.');}else{boat.x=nx;boat.z=nz;}state.fuel=Math.max(0,state.fuel-Math.abs(boat.speed)*dt*BALANCE.fuelPerSecond/(1+state.upgrades.motor*.2));}
if(charging){chargeT+=dt;power=pingPong(chargeT*.8);}fishing.charge=charging?power:null;
const result=fishing.update(dt,reel,storm);if(result==='escaped'){beep(150);toast(fishing.lastFail==='timeout'?'O peixe soltou a isca. Fisgue mais rápido na próxima.':'O peixe escapou. Mantenha-o dentro da zona verde.');}else if(result&&typeof result==='object'){const def=FISH.find(f=>f.id===result.species),price=economy.price(result),stored=economy.add(result);showCatchReveal(def,result.weight,price,stored);if(stored){toast(`${def.name} (${def.rarity}) · ${result.weight.toFixed(2)} kg · ◈ ${price} no porão!`);const bp=bobberPos(boat,fishing.castDistance);world.ripple(bp.x,bp.z,1);save();}else toast('Porão cheio! Venda os peixes no porto para liberar espaço.');}if(fishing.state==='bite'&&lastFishState!=='bite')beep(1100);lastFishState=fishing.state;const dmg=shark.update(dt,zone()>0);if(dmg){state.hull=Math.max(0,state.hull-dmg/(1+state.upgrades.hull*.45));beep(90);toast('Impacto no casco! Use a lança na próxima aproximação.');if(state.hull<=0)rescue();}if(motorOsc)motorOsc.frequency.value=40+Math.abs(boat.speed)*10;saveTimer+=dt;if(saveTimer>10){save();saveTimer=0;}}world.update(dt,clock,boat,state,fishing,shark,orbit,storm,spear);}powerUI();if(!paused&&(fishing.state==='bite'||fishing.state==='reeling'))minigame.draw(dt,fishing,reel);reveal.draw(dt);uiTimer+=dt;if(uiTimer>.1){ui();uiTimer=0;}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').style.opacity=0;}}
ui();requestAnimationFrame(frame);
